// Generates both apps' design-system files from brand/brand.json + brand/tokens.json.
//   npm run brand            write the generated files
//   npm run brand -- --check  exit 1 if any generated file is out of date (for CI / pre-commit)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => JSON.parse(fs.readFileSync(path.join(root, p), 'utf8'));
const brand = read('brand/brand.json');
const t = read('brand/tokens.json');
const HEADER = '// GENERATED by brand/build.mjs from brand/tokens.json + brand.json. Edit those, then run `npm run brand`.\n';
const CSS_HEADER = '/* GENERATED by brand/build.mjs from brand/tokens.json. Edit that, then run `npm run brand`. */\n';

const key = (k) => (/^[A-Za-z_$][\w$]*$/.test(k) || /^\d+(\.\d+)?$/.test(k) ? k : `'${k}'`);
const val = (v) => (typeof v === 'string' ? `'${v}'` : String(v));
const obj = (o, indent = '  ') => `{\n${Object.entries(o).map(([k, v]) => `${indent}${key(k)}: ${val(v)},`).join('\n')}\n}`;

// ---- mobile ----
const palette = `${HEADER}export const palette = ${obj(t.color)} as const;\n`;
const fonts = t.font.native;
const typography = `${HEADER}export const fontFamilies = ${obj(fonts)} as const;

export const typographyTokens = {
${Object.entries(t.typography).map(([k, v]) =>
  `  ${k}: { fontFamily: fontFamilies.${v.font}, fontSize: ${v.size}, lineHeight: ${v.lineHeight}, letterSpacing: ${v.letterSpacing} },${v.note ? ` // ${v.note}` : ''}`).join('\n')}
} as const;
`;
const spacing = `${HEADER}// 4 px scale: key x 4 = px (Tailwind's numbering, shared with admin): theme.spacing[3] is 12.
// The named steps are the original scale, kept so existing code keeps working.
export const spacing = {
  ${Object.entries(t.spacing.named).map(([k, v]) => `${k}: ${v}`).join(', ')},
  ${Object.entries(t.spacing.scale).map(([k, v]) => `${k}: ${v}`).join(', ')},
} as const;
`;
const radii = `${HEADER}// Corner radii. pill also rounds any square into a circle (it clamps to half the side).
export const radii = { ${Object.entries(t.radius).map(([k, v]) => `${k}: ${v}`).join(', ')} } as const;
`;
const shadows = `${HEADER}import { palette } from './palette';

export const shadows = {
${Object.entries(t.shadow).map(([k, s]) =>
  `  ${k}: { shadowColor: palette.${s.color}, shadowOpacity: ${s.opacity}, shadowRadius: ${s.radius}, shadowOffset: { width: 0, height: ${s.offsetY} }, elevation: ${s.elevation} },`).join('\n')}
} as const;
`;
const mobileBrand = `${HEADER}export const brand = { name: ${val(brand.name)}, wordmark: ${val(brand.logo.wordmark)} } as const;\n`;

// ---- admin ----
const px = (v) => `${v}px`;
const webText = Object.entries(t.webText).map(([k, ref]) => [k, px(typeof ref === 'number' ? ref : t.typography[ref].size)]);
const brandCss = `${CSS_HEADER}@theme inline {
    --font-sans: ${t.font.web};
${webText.map(([k, v]) => `    --text-${k}: ${v};`).join('\n')}
${Object.entries(t.tracking).map(([k, v]) => `    --tracking-${k}: ${v};`).join('\n')}
${t.webRadius.map((k) => `    --radius-${k}: ${px(t.radius[k])};`).join('\n')}
}

:root {
${Object.entries(t.color).map(([k, v]) => `    --palette-${k}: ${v};`).join('\n')}
}
`;
const adminBrand = `${HEADER}export const brand = { name: ${val(brand.name)}, adminName: ${val(brand.adminName)}, wordmark: ${val(brand.logo.wordmark)} } as const;

/** Custom Tailwind steps from src/brand.css, so cn() merges them as sizes rather than colours. */
export const themeClassNames = {
  text: [${webText.map(([k]) => val(k)).join(', ')}],
  radius: [${t.webRadius.map(val).join(', ')}],
  tracking: [${Object.keys(t.tracking).map(val).join(', ')}],
};
`;

// ---- names baked into native/web config ----
const appJsonPath = 'mobile/app.json';
const appJson = read(appJsonPath);
appJson.expo.name = brand.name;
const indexHtmlPath = 'admin/index.html';
const indexHtml = fs.readFileSync(path.join(root, indexHtmlPath), 'utf8').replace(/<title>[^<]*<\/title>/, `<title>${brand.adminName}</title>`);

const outputs = {
  'mobile/src/core/theme/tokens/palette.ts': palette,
  'mobile/src/core/theme/tokens/typography.ts': typography,
  'mobile/src/core/theme/tokens/spacing.ts': spacing,
  'mobile/src/core/theme/tokens/radii.ts': radii,
  'mobile/src/core/theme/tokens/shadows.ts': shadows,
  'mobile/src/core/brand/brand.ts': mobileBrand,
  [appJsonPath]: JSON.stringify(appJson, null, 2) + '\n',
  'admin/src/brand.css': brandCss,
  'admin/src/lib/brand.ts': adminBrand,
  [indexHtmlPath]: indexHtml,
};

const check = process.argv.includes('--check');
const stale = [];
for (const [rel, content] of Object.entries(outputs)) {
  const file = path.join(root, rel);
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (current === content) continue;
  if (check) stale.push(rel);
  else {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content);
    console.log('wrote', rel);
  }
}
if (check && stale.length) {
  console.error(`Brand files out of date (run \`npm run brand\`):\n  ${stale.join('\n  ')}`);
  process.exit(1);
}
